/* LISTENING — Conversations, Announcements, Academic Talks */
const N2 = { W: 'Woman', M: 'Man' };
CONTENT.conv = [
  { id: 'v01', diff: 2, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['W', 'Hey, are you still coming to the study group tonight? We\'re meeting at seven in the library.'], ['M', 'I was planning to, but my manager asked me to cover for a colleague who called in sick, so I won\'t be finished at the café until nine.'], ['W', 'That\'s a shame. We\'re going over chapter five on market structures, and I know that\'s the part you were struggling with.'], ['M', 'Tell me about it. Is there any chance you could send me your notes afterward? I\'d like to read them before Friday\'s quiz.'], ['W', 'Sure. I\'ll photograph the pages and send them tonight, so you\'ll have them before you go to bed.']],
    qs: [{ q: 'Why can\'t the man go to the study group?', o: ['He is ill himself', 'He has already studied chapter five', 'He has to cover for a coworker', 'He forgot about the meeting'], a: 2, x: '« cover for a colleague who called in sick » : il doit remplacer un collègue au café.' }, { q: 'What does the conversation suggest about chapter five?', o: ['It is difficult for the man', 'It will not be on the quiz', 'It was covered last week', 'It is the shortest chapter'], a: 0, x: '« the part you were struggling with » puis « Tell me about it » : le chapitre lui pose problème.' }, { q: 'What will the woman do?', o: ['Explain the chapter to him in person tomorrow', 'Send him photos of her notes tonight', 'Postpone the study group', 'Ask the professor for extra help'], a: 1, x: '« I\'ll photograph the pages and send them tonight ».' }] },
  { id: 'v02', diff: 2, ctx: 'Listen to a conversation between a student and a librarian.', names: { W: 'Librarian', M: 'Student' }, lines: [['M', 'Hi, I\'m looking for a book that\'s on reserve for my economics course, but the system says it\'s checked out.'], ['W', 'Reserve books can only be borrowed for two hours. Someone probably has it right now. It should be back by three.'], ['M', 'I have class at three. Is there another copy anywhere?'], ['W', 'Actually, we have an electronic version. You can read it online with your student login, though you can only download one chapter at a time.'], ['M', 'Perfect, one chapter is all I need.']],
    qs: [{ q: 'What is the student\'s problem?', o: ['He lost a library book', 'He cannot log in to the system', 'He owes a late fee', 'The book he needs is currently borrowed by someone else'], a: 3, x: 'Le livre est « checked out ».' }, { q: 'What can be inferred about the student\'s needs?', o: ['He needs the entire book', 'He will wait until three', 'He prefers printed books', 'The electronic version will be sufficient for him'], a: 3, x: '« one chapter is all I need ».' }] },
  { id: 'v03', diff: 2, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'Did you see that the internship application now requires a video?'], ['W', 'Yeah, a two-minute introduction. Honestly, I\'m dreading it. I freeze up in front of a camera.'], ['M', 'Why don\'t you practice with me? I\'ll record you on my phone a few times until you feel more comfortable.'], ['W', 'That would actually help a lot. How about Thursday after lunch?'], ['M', 'Works for me.']],
    qs: [{ q: 'How does the woman feel about the video?', o: ['Excited', 'Indifferent', 'Anxious', 'Confident'], a: 2, x: '« I\'m dreading it. I freeze up ».' }, { q: 'What does the man offer to do?', o: ['Make the video for her', 'Help her rehearse by recording her', 'Write her introduction', 'Contact the company'], a: 1, x: 'Il propose de l\'enregistrer plusieurs fois pour s\'entraîner.' }] },
  { id: 'v04', diff: 2, ctx: 'Listen to a conversation between a student and a professor.', names: { W: 'Professor', M: 'Student' }, lines: [['M', 'Professor Hall, I wanted to ask about my paper topic. I\'d like to look at how microfinance affects women entrepreneurs.'], ['W', 'It\'s a rich topic, but as it stands, it\'s far too broad for ten pages. You\'d be skimming the surface.'], ['M', 'So I should narrow it down?'], ['W', 'Exactly. Pick one region, maybe even one lending program, and look at a specific outcome, like whether borrowers expanded their businesses. And make sure there\'s actually data available before you commit.'], ['M', 'That makes sense. I\'ll check the databases this weekend.']],
    qs: [{ q: 'What is the professor\'s main concern?', o: ['The topic is too general for a short paper', 'The topic is irrelevant to the course', 'The student lacks experience', 'Microfinance has been studied too much'], a: 0, x: '« far too broad for ten pages ».' }, { q: 'What does the professor advise the student to do before committing to a topic?', o: ['Confirm that relevant data exist', 'Interview entrepreneurs', 'Write the introduction', 'Choose a different subject'], a: 0, x: '« make sure there\'s actually data available ».' }] },
  { id: 'v05', diff: 2, ctx: 'Listen to a conversation at a campus café.', names: { W: 'Server', M: 'Student' }, lines: [['W', 'Hi there, what can I get you?'], ['M', 'A large coffee and a blueberry muffin, please.'], ['W', 'I\'m afraid we sold out of blueberry about ten minutes ago. We\'ve still got banana nut and double chocolate, though.'], ['M', 'Hmm. I\'m trying to cut down on sugar, so banana nut sounds like the better option. Do you take cards, or is it cash only?'], ['W', 'We take cards, but the machine is a bit slow today, so bear with me.']],
    qs: [{ q: 'Why can\'t the man get the muffin he first asked for?', o: ['He cannot afford it', 'The café is about to close', 'The café has run out of that kind', 'It contains an ingredient he avoids'], a: 2, x: '« we sold out of blueberry about ten minutes ago ».' }, { q: 'Why does the man choose the banana nut muffin?', o: ['It is the cheapest one', 'He thinks it is less sweet than the chocolate one', 'It is his favorite flavor', 'The server recommended it'], a: 1, x: '« trying to cut down on sugar » : il veut moins de sucre, donc évite le chocolat.' }, { q: 'What difficulty might the man have when paying?', o: ['The café accepts only cash', 'The prices have gone up', 'The cashier is new', 'The card machine is slow'], a: 3, x: '« the machine is a bit slow today ».' }] },
  { id: 'v06', diff: 2, ctx: 'Listen to a conversation between two roommates.', names: N2, lines: [['W', 'The electricity bill came in, and it\'s almost double last month\'s.'], ['M', 'Seriously? It must be the heater in the living room. It\'s been on all day.'], ['W', 'Maybe we could set a timer so it only runs in the evening, when we\'re actually home.'], ['M', 'Good idea. And let\'s split this bill three ways as usual. I\'ll let Sam know.']],
    qs: [{ q: 'What does the man think caused the high bill?', o: ['A mistake by the company', 'Their new roommate', 'Higher prices', 'The heater running all day'], a: 3, x: '« It must be the heater... on all day ».' }, { q: 'What does the woman suggest?', o: ['Buying a new heater', 'Calling the company', 'Using a timer on the heater', 'Paying the bill alone'], a: 2, x: '« set a timer so it only runs in the evening ».' }] },
  { id: 'v07', diff: 3, ctx: 'Listen to a conversation between a student and an academic advisor.', names: { W: 'Advisor', M: 'Student' }, lines: [['M', 'I\'m thinking of taking five courses next semester so I can graduate early.'], ['W', 'That\'s ambitious. Which courses?'], ['M', 'Econometrics, corporate finance, two electives, and the thesis seminar.'], ['W', 'Econometrics and the thesis seminar together are notoriously demanding. Students who combine them often end up with lower grades in both. If your goal is a finance master\'s, your grades in those courses will matter more than graduating a semester early.'], ['M', 'Hmm, so maybe I should drop one of the electives instead.'], ['W', 'That would be a sensible compromise.']],
    qs: [{ q: 'Why is the advisor concerned?', o: ['The workload could hurt grades in important courses', 'The student has not paid tuition', 'The electives are not recognized', 'The thesis seminar is full'], a: 0, x: 'Econometrics + thesis seminar = très exigeant, risque pour les notes.' }, { q: 'What does the advisor imply about graduating early?', o: ['It is the most important goal', 'It is less important than strong grades for his plans', 'It is impossible', 'It is required for a master\'s'], a: 1, x: '« grades in those courses will matter more than graduating a semester early ».' }] },
  { id: 'v08', diff: 2, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'Do you happen to know if the pool is open today? I wanted to swim a few laps before my exam this afternoon.'], ['W', 'I think it\'s closed until Wednesday. They\'re draining it to clean the tiles. I saw a notice on the door.'], ['M', 'Oh, great. That throws my whole routine off. Swimming is how I calm my nerves before a test.'], ['W', 'Why don\'t you try the municipal pool downtown? It\'s only about fifteen minutes by bike.'], ['M', 'I might do that. I\'ll have to be quick, though. My exam starts at two.']],
    qs: [{ q: 'Why does the man want to go swimming?', o: ['To train for a competition', 'To meet friends', 'To lose weight', 'To relax before his exam'], a: 3, x: '« Swimming is how I calm my nerves before a test ».' }, { q: 'Why is the pool unavailable?', o: ['It is being cleaned', 'It is reserved for a team', 'It is closed for a holiday', 'It is waiting for repairs'], a: 0, x: '« They\'re draining it to clean the tiles ».' }, { q: 'What does the woman suggest?', o: ['Using a pool in the city center', 'Waiting until Wednesday', 'Skipping the swim altogether', 'Asking the sports center for a refund'], a: 0, x: 'Elle propose la piscine municipale du centre-ville, à quinze minutes à vélo.' }] },
  { id: 'v09', diff: 2, ctx: 'Listen to a conversation between a student and a housing office employee.', names: { W: 'Employee', M: 'Student' }, lines: [['M', 'Hi, I\'d like to request a room change. My room is right above the kitchen, and it\'s really noisy early in the morning.'], ['W', 'I understand. Room changes are processed after the first two weeks of the semester, so you\'d have to wait until next Monday to apply.'], ['M', 'Is there anything I can do before that?'], ['W', 'You can fill out the form now, and I\'ll put you at the top of the list once the period opens.']],
    qs: [{ q: 'Why does the student want to change rooms?', o: ['It is too small', 'It is too noisy', 'It is too expensive', 'It is far from campus'], a: 1, x: 'Bruit de la cuisine le matin.' }, { q: 'What will the employee do?', o: ['Change his room immediately', 'Refuse the request', 'Give his request priority when changes begin', 'Talk to the kitchen staff'], a: 2, x: '« put you at the top of the list ».' }] },
  { id: 'v10', diff: 3, ctx: 'Listen to a conversation between two classmates working on a project.', names: N2, lines: [['W', 'I\'ve been going through the survey responses, and something\'s off. Almost everyone rated the product five stars.'], ['M', 'Isn\'t that good news?'], ['W', 'Not if it\'s too good to be true. We only surveyed people who follow the brand on social media. They\'re already fans.'], ['M', 'Ah, so the sample\'s biased. Should we scrap the data?'], ['W', 'Not scrap it — but we need to acknowledge the limitation and, ideally, collect responses from a random group of shoppers too.']],
    qs: [{ q: 'What problem does the woman identify?', o: ['The respondents were not representative', 'The survey had too few questions', 'The product received poor ratings', 'Some data were lost'], a: 0, x: 'Échantillon biaisé : des fans de la marque.' }, { q: 'What does the woman propose?', o: ['Deleting all the data', 'Changing the product', 'Publishing the results immediately', 'Reporting the limitation and gathering more varied responses'], a: 3, x: '« acknowledge the limitation and... collect responses from a random group ».' }] },
  { id: 'v11', diff: 2, ctx: 'Listen to a conversation between two friends.', names: N2, lines: [['W', 'Are you coming to Emma\'s birthday dinner on Friday? She booked a table at that Italian place near the station.'], ['M', 'I\'d love to, but my brother is visiting for the weekend, and I don\'t want to leave him on his own on his first night.'], ['W', 'Why not bring him along? Emma wouldn\'t mind at all. She\'s always saying the more, the merrier.'], ['M', 'That\'s kind of you, but I\'d feel awkward turning up with an extra person. Would you mind checking with her first?'], ['W', 'Not at all. I\'ll text her now and let you know.']],
    qs: [{ q: 'Why does the man hesitate to go to the dinner?', o: ['He doesn\'t want to leave his brother alone', 'He dislikes Italian food', 'He has an exam on Saturday', 'He wasn\'t invited'], a: 0, x: '« I don\'t want to leave him on his own on his first night ».' }, { q: 'What is the man worried about?', o: ['The cost of the dinner', 'Seeming rude if he brings a guest without asking', 'Whether his brother will enjoy the food', 'Arriving late'], a: 1, x: '« I\'d feel awkward turning up with an extra person ».' }, { q: 'What will the woman do next?', o: ['Book a bigger table', 'Cancel the dinner', 'Contact Emma about the brother', 'Invite other friends'], a: 2, x: '« I\'ll text her now and let you know ».' }] },
  { id: 'v12', diff: 2, ctx: 'Listen to a conversation between a student and a professor.', names: { M: 'Professor', W: 'Student' }, lines: [['W', 'Professor, I missed the quiz on Tuesday because I had the flu. Is there any way I can make it up?'], ['M', 'Do you have a note from the health center?'], ['W', 'Yes, I have it here.'], ['M', 'Good. In that case, instead of a make-up quiz, I\'ll just count your final exam a bit more heavily. That\'s my standard policy.'], ['W', 'Oh, okay. Thank you.']],
    qs: [{ q: 'What does the student want?', o: ['An extension on an essay', 'A higher grade', 'A note from the health center', 'A chance to make up a missed quiz'], a: 3, x: '« Is there any way I can make it up? »' }, { q: 'How will the professor handle the situation?', o: ['Give her a make-up quiz', 'Give her zero', 'Increase the weight of the final exam', 'Let her retake the course'], a: 2, x: '« count your final exam a bit more heavily ».' }] },
  { id: 'v13', diff: 3, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'So, did you decide between the consulting offer and the bank?'], ['W', 'Still torn. The consulting job pays more, but the travel is relentless — four days a week on the road.'], ['M', 'And the bank?'], ['W', 'Lower starting salary, but I\'d be on the M&A team, which is exactly what I want long-term. Plus, I could actually have a life.'], ['M', 'Sounds like you\'ve kind of already made up your mind.'], ['W', 'Maybe I have. I just needed to hear myself say it.']],
    qs: [{ q: 'What is the main drawback of the consulting job?', o: ['The amount of travel', 'The low salary', 'The location', 'The team'], a: 0, x: '« four days a week on the road ».' }, { q: 'What does the man imply?', o: ['The woman should choose consulting', 'The woman seems to prefer the bank', 'The woman should reject both offers', 'The woman needs more information'], a: 1, x: '« you\'ve kind of already made up your mind ».' }] },
  { id: 'v14', diff: 2, ctx: 'Listen to a conversation at a bookstore.', names: { W: 'Clerk', M: 'Student' }, lines: [['M', 'Excuse me, I\'m looking for the latest edition of "Introduction to Statistics".'], ['W', 'I\'m afraid we\'re sold out at the moment. We ordered extra copies after the semester started, and they should arrive on Thursday.'], ['M', 'Thursday might be too late. My first assignment is due on Friday. Could I use the older edition in the meantime?'], ['W', 'You could, though a few of the exercises were changed, so some questions won\'t match. I can put a copy aside for you and call you the moment it comes in. Can I take your name?'], ['M', 'It\'s Carlos. And yes, please, I\'ll come in as soon as it arrives.']],
    qs: [{ q: 'Why is the man worried about waiting until Thursday?', o: ['An assignment is due the next day', 'He is traveling on Thursday', 'The book will cost more by then', 'The store closes early on Thursday'], a: 0, x: '« My first assignment is due on Friday ».' }, { q: 'What is the drawback of using the older edition?', o: ['It is more expensive', 'Some of the exercises are different', 'It is missing several chapters', 'It is not allowed in class'], a: 1, x: '« a few of the exercises were changed ».' }, { q: 'What will the clerk do?', o: ['Order a different book for him', 'Give him a discount on the older edition', 'Set aside a copy and call him when it arrives', 'Lend him her own copy'], a: 2, x: '« I can put a copy aside for you and call you the moment it comes in ».' }] },
  { id: 'v15', diff: 2, ctx: 'Listen to a conversation between two teammates.', names: N2, lines: [['W', 'Our presentation is twelve minutes, and the limit is ten.'], ['M', 'We could cut the history section. It\'s interesting, but it doesn\'t really support our main argument.'], ['W', 'Agreed. And I can speed up the data part if I skip the second chart.'], ['M', 'Let\'s rehearse again tomorrow and time it.']],
    qs: [{ q: 'What is the problem with the presentation?', o: ['It is too long', 'It is too short', 'It lacks data', 'It has no main argument'], a: 0, x: '12 minutes pour une limite de 10.' }, { q: 'Why does the man suggest removing the history section?', o: ['It is inaccurate', 'It is boring', 'It is too difficult', 'It is not essential to their argument'], a: 3, x: '« it doesn\'t really support our main argument ».' }] },
  { id: 'v16', diff: 2, ctx: 'Listen to a conversation between a student and a teaching assistant.', names: { M: 'TA', W: 'Student' }, lines: [['W', 'I don\'t understand why I lost points on question three. My final answer was correct.'], ['M', 'It was, but the question asked you to justify each step. You jumped from the equation straight to the result, so there was no way to tell whether you understood the method or just got lucky.'], ['W', 'So the reasoning matters as much as the answer.'], ['M', 'In this course, even more. On the final, a correct answer with no working will get at most half credit.']],
    qs: [{ q: 'Why did the student lose points?', o: ['Her answer was wrong', 'She did not show her reasoning', 'She answered the wrong question', 'She submitted late'], a: 1, x: 'Elle n\'a pas justifié chaque étape.' }, { q: 'What does the TA say about the final exam?', o: ['Only final answers will be graded', 'It will not include question three', 'It will be easier', 'Answers without explanation will receive limited credit'], a: 3, x: '« at most half credit ».' }] },
  { id: 'v17', diff: 2, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'Do you know which room the chemistry exam is in? The schedule online still says Room 204.'], ['W', 'That\'s out of date. They moved it to the main hall because far more people registered than expected. Room 204 only seats about eighty. They sent an email on Monday.'], ['M', 'I never saw it. It must have gone to my junk folder. I would have turned up at the wrong place and missed the start.'], ['W', 'You should check your spam folder more often, then. And bring your student card, because they\'ll be checking ID at the door.'], ['M', 'Thanks for the heads-up. I owe you a coffee.']],
    qs: [{ q: 'Why was the exam moved?', o: ['The room is being renovated', 'The professor wanted a quieter room', 'More students registered than the room could hold', 'The schedule contained an error'], a: 2, x: '« far more people registered than expected ».' }, { q: 'Why didn\'t the man know about the change?', o: ['The email probably ended up in his junk folder', 'He ignores all university emails', 'The online schedule was correct', 'He was absent on Monday'], a: 0, x: '« It must have gone to my junk folder ».' }, { q: 'What does the woman tell the man to bring?', o: ['His student card', 'A calculator', 'A printed copy of the email', 'A pen and a notebook'], a: 0, x: '« bring your student card, because they\'ll be checking ID ».' }] },
  { id: 'v18', diff: 2, ctx: 'Listen to a conversation between a student and a campus IT technician.', names: { W: 'Technician', M: 'Student' }, lines: [['M', 'My laptop keeps disconnecting from the campus Wi-Fi.'], ['W', 'Has this been happening since the update last week?'], ['M', 'Now that you mention it, yes.'], ['W', 'Then you probably need to reinstall the network certificate. It takes five minutes. Let me show you.']],
    qs: [{ q: 'What is the student\'s problem?', o: ['His laptop is broken', 'He forgot his password', 'His battery dies quickly', 'He loses his internet connection'], a: 3, x: 'Déconnexions du Wi-Fi.' }, { q: 'What is the likely cause?', o: ['A virus', 'A recent update', 'An old laptop', 'Too many users'], a: 1, x: 'Depuis la mise à jour → certificat à réinstaller.' }] },
  { id: 'v19', diff: 3, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['W', 'Have you started reading for the ethics seminar? The article is sixty pages.'], ['M', 'I skimmed it. The gist is that companies shouldn\'t only maximize profits for shareholders, but I found the argument a bit one-sided.'], ['W', 'How so?'], ['M', 'The author barely addresses the obvious counterargument — that managers who pursue vague social goals become harder to hold accountable.'], ['W', 'That\'s a good point to raise in class, actually.']],
    qs: [{ q: 'What is the man\'s opinion of the article?', o: ['It neglects an important opposing argument', 'It is excellent and balanced', 'It is too short', 'It is only about shareholders'], a: 0, x: '« one-sided... barely addresses the obvious counterargument ».' }, { q: 'What does the woman suggest?', o: ['That he read it more carefully', 'That he change seminars', 'That he share his criticism in class', 'That he write to the author'], a: 2, x: '« That\'s a good point to raise in class ».' }] },
  { id: 'v20', diff: 2, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['W', 'I\'m planning to take a taxi to the airport on Friday. Do you want to share it? It would work out cheaper for both of us.'], ['M', 'Definitely. What time is your flight?'], ['W', 'Two o\'clock, so I\'d like to leave around eleven to be safe. Last time, the traffic on the ring road was terrible.'], ['M', 'That works for me. My flight\'s not until two thirty, but I\'d rather wait at the airport than risk missing it.'], ['W', 'Great. I\'ll book it tonight and we can split the fare afterward.']],
    qs: [{ q: 'Why does the woman suggest sharing a taxi?', o: ['It is faster than the train', 'She doesn\'t know the way', 'Her flight leaves early in the morning', 'It would be cheaper for both of them'], a: 3, x: '« It would work out cheaper for both of us ».' }, { q: 'Why does she want to leave at eleven?', o: ['To allow for possible traffic delays', 'Her flight leaves at eleven', 'The taxi service is limited', 'She has to check out of her residence'], a: 0, x: '« to be safe. Last time, the traffic on the ring road was terrible ».' }, { q: 'What can be inferred about the man\'s flight?', o: ['It leaves before hers', 'It has been cancelled', 'It leaves later than hers, but he will still go early', 'It leaves from a different airport'], a: 2, x: 'Son vol est à 14 h 30 mais il préfère attendre à l\'aéroport.' }] },
  { id: 'v21', diff: 2, ctx: 'Listen to a conversation between a student and a career counselor.', names: { W: 'Counselor', M: 'Student' }, lines: [['M', 'I\'ve applied to fifteen internships and haven\'t heard back from any of them.'], ['W', 'Can I see the cover letter you\'ve been using?'], ['M', 'Sure, it\'s the same one for all of them.'], ['W', 'That might be the issue. Recruiters can tell when a letter is generic. Mention something specific about each company and why you\'d fit their team.']],
    qs: [{ q: 'What does the counselor think the problem is?', o: ['The student applied to too few companies', 'His cover letter is too generic', 'His grades are too low', 'He applied too late'], a: 1, x: 'La même lettre pour tous = générique.' }, { q: 'What does the counselor advise?', o: ['Applying to more companies', 'Tailoring each letter to the company', 'Calling recruiters directly', 'Removing the cover letter'], a: 1, x: 'Personnaliser chaque lettre.' }] },
  { id: 'v22', diff: 3, ctx: 'Listen to a conversation between two members of a student investment club.', names: N2, lines: [['M', 'I think we should put most of the club\'s fund into that renewable energy stock. It\'s up forty percent this year.'], ['W', 'That\'s exactly what worries me. We\'d be buying after the big run-up, and putting most of the fund in one company is a huge concentration risk.'], ['M', 'But the sector has strong tailwinds.'], ['W', 'Sure, so why not buy a sector fund instead? We\'d get the exposure without betting everything on a single firm.']],
    qs: [{ q: 'What is the woman\'s main concern?', o: ['Renewable energy has no future', 'The club has no money', 'The stock price is too low', 'The investment would be too concentrated'], a: 3, x: '« a huge concentration risk ».' }, { q: 'What does the woman propose?', o: ['Investing nothing', 'Selling all stocks', 'Buying a diversified fund in the same sector', 'Waiting a year'], a: 2, x: '« a sector fund... without betting everything on a single firm ».' }] },
  { id: 'v23', diff: 2, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'Your presentation was fantastic! I could tell you\'d prepared thoroughly, especially the section on consumer trends.'], ['W', 'Thanks, that\'s a relief. I was so nervous my hands were shaking. Did I rush through the introduction?'], ['M', 'A little, yes. You were going a bit fast in the first couple of minutes, but then you settled down and it was really easy to follow.'], ['W', 'I\'ll slow down next time. Good luck with yours, by the way. When is it?'], ['M', 'Thursday, and I\'m already dreading it.']],
    qs: [{ q: 'How did the woman feel while she was presenting?', o: ['Very nervous', 'Completely relaxed', 'Bored', 'Annoyed'], a: 0, x: '« I was so nervous my hands were shaking ».' }, { q: 'What was the only weakness the man noticed?', o: ['She forgot part of her talk', 'She spoke too quietly', 'She ran out of time', 'She spoke too quickly at the beginning'], a: 3, x: '« a bit fast in the first couple of minutes ».' }, { q: 'How does the man feel about his own presentation?', o: ['He has already given it', 'He is worried about it', 'He plans to skip it', 'He is eager to start'], a: 1, x: '« Thursday, and I\'m already dreading it ».' }] },
  { id: 'v24', diff: 2, ctx: 'Listen to a conversation between a student and a professor.', names: { M: 'Professor', W: 'Student' }, lines: [['W', 'I\'m interested in your research on consumer behavior. Are you taking research assistants this summer?'], ['M', 'I might have one position. Have you taken the research methods course?'], ['W', 'I\'m taking it now.'], ['M', 'Good. Send me your CV and a short paragraph on why you\'re interested. I\'ll decide by the end of the month.']],
    qs: [{ q: 'Why does the student visit the professor?', o: ['To ask about a grade', 'To discuss a paper', 'To ask about a research assistant position', 'To register for a course'], a: 2, x: 'Poste d\'assistant de recherche.' }, { q: 'What does the professor ask the student to send?', o: ['A transcript', 'A CV and a brief statement of interest', 'A research proposal', 'Two recommendation letters'], a: 1, x: '« your CV and a short paragraph ».' }] },
  { id: 'v25', diff: 2, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['W', 'I read that the university is replacing some lectures with recorded videos to cut costs.'], ['M', 'Honestly, for big intro courses, I don\'t see the harm. I barely ask questions in a room of four hundred people anyway.'], ['W', 'Maybe, but at least the lecture forces you to show up. With videos, I know I\'d fall behind.'], ['M', 'Fair. I guess it depends on how disciplined you are.']],
    qs: [{ q: 'What is the man\'s view of recorded lectures for large courses?', o: ['They are acceptable', 'They are harmful', 'They are better than seminars', 'They should be banned'], a: 0, x: '« I don\'t see the harm ».' }, { q: 'Why is the woman skeptical?', o: ['She would be less likely to keep up without attending', 'Videos are low quality', 'She likes asking questions', 'Videos are expensive'], a: 0, x: '« With videos, I know I\'d fall behind ».' }] },
  { id: 'v26', diff: 2, ctx: 'Listen to a conversation at the student health center.', names: { W: 'Receptionist', M: 'Student' }, lines: [['M', 'Hi, I\'d like to see a doctor today. I\'ve had a sore throat for three days.'], ['W', 'We don\'t have any appointments left today, but there\'s a walk-in clinic from four to six. You might have to wait a bit.'], ['M', 'That\'s fine. I\'ll come back at four.']],
    qs: [{ q: 'Why can\'t the student get an appointment?', o: ['The clinic is closed', 'All appointments are taken', 'He needs insurance', 'The doctor is sick'], a: 1, x: '« We don\'t have any appointments left today ».' }, { q: 'What will the student do?', o: ['Go to a hospital', 'Book for tomorrow', 'Come back during walk-in hours', 'Call later'], a: 2, x: '« I\'ll come back at four ».' }] },
  { id: 'v27', diff: 3, ctx: 'Listen to a conversation between a student and a professor after class.', names: { W: 'Professor', M: 'Student' }, lines: [['M', 'In today\'s lecture, you said minimum wage increases don\'t necessarily reduce employment. But isn\'t that what the supply and demand model predicts?'], ['W', 'In a perfectly competitive labor market, yes. But when a few employers dominate a local market, they can pay below what workers produce. In that case, a moderate minimum wage can actually increase employment.'], ['M', 'So the basic model is just a special case.'], ['W', 'Exactly. That\'s the key takeaway for next week\'s problem set.']],
    qs: [{ q: 'What confused the student?', o: ['The date of the problem set', 'The professor\'s grading', 'The definition of employment', 'A claim that seemed to contradict a basic model'], a: 3, x: 'Contradiction apparente avec l\'offre et la demande.' }, { q: 'According to the professor, when might a minimum wage increase employment?', o: ['When markets are perfectly competitive', 'When unemployment is zero', 'When wages are already high', 'When a few employers dominate the local labor market'], a: 3, x: 'Situation de monopsone : peu d\'employeurs.' }] },
  { id: 'v28', diff: 2, ctx: 'Listen to a conversation between two neighbors in a residence hall.', names: N2, lines: [['W', 'Hi, sorry to bother you. I don\'t want to be a pain, but could you turn your music down a little? I\'ve got an exam first thing tomorrow, and I\'m trying to go over my notes.'], ['M', 'Oh, I\'m really sorry. I had no idea it was so loud. I\'ll put my headphones on.'], ['W', 'Thanks. I can hear the bass quite clearly through the wall, that\'s the problem.'], ['M', 'No worries. Good luck tomorrow! What\'s the exam on?'], ['W', 'Organic chemistry, so I\'ll need it.']],
    qs: [{ q: 'Why does the woman ask the man to lower the volume?', o: ['She needs to study for an exam', 'She is trying to sleep', 'She dislikes his music', 'She is on the phone'], a: 0, x: '« I\'ve got an exam first thing tomorrow ».' }, { q: 'How does the man react?', o: ['He politely refuses', 'He apologizes and offers to use headphones', 'He becomes annoyed', 'He says he will stop playing music for the week'], a: 1, x: '« I\'m really sorry... I\'ll put my headphones on ».' }, { q: 'What can be inferred about the man?', o: ['He is taking the same exam', 'He has been asked to be quiet before', 'He did not realize the music was disturbing her', 'He does not own headphones'], a: 2, x: '« I had no idea it was so loud ».' }] },
  { id: 'v29', diff: 2, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'I\'m thinking of studying abroad next year, but I\'m worried about the cost.'], ['W', 'Have you looked at the exchange programs? You pay your normal tuition here, not the foreign university\'s.'], ['M', 'Really? That changes everything. Where do I find the list?'], ['W', 'The international office website. The deadline is in November, though.']],
    qs: [{ q: 'What is the man worried about?', o: ['The language', 'His grades', 'Being far from family', 'The cost'], a: 3, x: '« worried about the cost ».' }, { q: 'Why does the man say "That changes everything"?', o: ['The deadline has passed', 'He no longer wants to go abroad', 'Exchange programs would be more affordable than he thought', 'He found a scholarship'], a: 2, x: 'Il paierait les frais de son université, pas ceux de l\'étranger.' }] },
  { id: 'v30', diff: 3, ctx: 'Listen to a conversation between two students preparing for a debate.', names: N2, lines: [['W', 'We\'re arguing that cities should ban cars from their centers. What\'s our strongest point?'], ['M', 'Air quality. The health data are hard to dispute.'], ['W', 'Agreed. But the other team will say it hurts small shops.'], ['M', 'Then we pre-empt it. Several cities saw retail sales rise after pedestrianization because people linger longer when streets are pleasant.'], ['W', 'Nice. Let\'s make sure we cite specific examples, not just claim it.']],
    qs: [{ q: 'What does the man mean by "we pre-empt it"?', o: ['They will address the objection before the other team raises it', 'They will ignore the argument', 'They will change their position', 'They will ask for more time'], a: 0, x: 'Anticiper l\'objection.' }, { q: 'What does the woman insist on?', o: ['Speaking more loudly', 'Using specific evidence', 'Avoiding health arguments', 'Changing the topic'], a: 1, x: '« cite specific examples, not just claim it ».' }] },
];

CONTENT.ann = [
  { id: 'n01', diff: 2, g: 'W', ctx: 'Listen to an announcement at the beginning of a class.', text: 'Good morning, everyone. Before we get started, I need to correct a mistake in the syllabus. It says your group projects are due this Friday, but that was a typo. The deadline is actually next Friday, so you have an extra week. I\'ve also uploaded the grading rubric to the course website, and I strongly suggest you read it carefully before you finalize your work, because a large share of the marks depends on how well you structure your argument. If you have questions, come and see me during office hours rather than emailing me the night before the deadline.',
    qs: [{ q: 'What is the main purpose of the announcement?', o: ['To cancel the group projects', 'To assign students to groups', 'To correct a deadline and point students to the grading criteria', 'To introduce a new topic'], a: 2, x: 'Correction de la date + rubrique de notation en ligne.' }, { q: 'What is true about the project deadline?', o: ['It is a week later than the syllabus states', 'It has been moved earlier', 'It is unchanged', 'It has been cancelled'], a: 0, x: '« due next Friday... you have an extra week ».' }, { q: 'What does the professor recommend before students finalize their work?', o: ['Emailing her a draft', 'Reading the grading rubric', 'Changing groups', 'Submitting early'], a: 1, x: '« I strongly suggest you read it carefully before you finalize your work ».' }] },
  { id: 'n02', diff: 2, g: 'M', ctx: 'Listen to an announcement on the campus radio.', text: 'Attention, students. Due to the snowstorm expected tonight, all classes scheduled before noon tomorrow are cancelled. Afternoon classes will run as normal unless you receive an email saying otherwise. The dining halls will remain open, but the shuttle service will be suspended until the roads are cleared. Please avoid unnecessary travel.',
    qs: [{ q: 'Which classes are cancelled?', o: ['All classes tomorrow', 'Afternoon classes tomorrow', 'Evening classes tonight', 'Morning classes tomorrow'], a: 3, x: '« all classes scheduled before noon ».' }, { q: 'What service will stop temporarily?', o: ['The dining halls', 'The shuttle', 'Email', 'The library'], a: 1, x: 'La navette est suspendue.' }, { q: 'How will students know if afternoon classes are cancelled?', o: ['On the radio', 'From their roommates', 'By email', 'On a sign'], a: 2, x: '« unless you receive an email saying otherwise ».' }] },
  { id: 'n03', diff: 2, g: 'W', ctx: 'Listen to an announcement in a university library.', text: 'May I have your attention, please. The library will be closing in fifteen minutes. Please bring any items you wish to borrow to the front desk now, as the self-checkout machines have already been shut down for the night. Group study rooms must be vacated immediately. Thank you, and have a good evening.',
    qs: [{ q: 'What is the announcement mainly about?', o: ['The library closing soon', 'The library\'s new hours', 'A lost item', 'A new study room'], a: 0, x: 'Fermeture dans 15 minutes.' }, { q: 'Why must students go to the front desk to borrow books?', o: ['The desk offers longer loans', 'Books are free there', 'The machines are broken permanently', 'The self-checkout machines are turned off'], a: 3, x: 'Automates déjà éteints.' }, { q: 'What must students in group study rooms do?', o: ['Wait fifteen minutes', 'Leave right away', 'Return their keys tomorrow', 'Lower their voices'], a: 1, x: '« must be vacated immediately ».' }] },
  { id: 'n04', diff: 3, g: 'M', ctx: 'Listen to an announcement made by a professor at the start of a lecture.', text: 'Before we begin, I want to address the midterm results. The class average was considerably lower than in previous years, and after reviewing the exam, I believe question four was ambiguously worded. So I\'ve decided to accept two interpretations of that question and regrade it accordingly. You\'ll see updated scores online by Thursday. If your grade doesn\'t change, it means your original answer was already credited.',
    qs: [{ q: 'Why is the professor regrading part of the exam?', o: ['Students complained about the time limit', 'One question could be understood in more than one way', 'The average was too high', 'Some exams were lost'], a: 1, x: '« ambiguously worded ».' }, { q: 'What does it mean if a student\'s grade stays the same?', o: ['The regrading has not happened yet', 'The student failed question four', 'The student must contact the professor', 'The student\'s answer had already received credit'], a: 3, x: '« your original answer was already credited ».' }, { q: 'When will updated scores be available?', o: ['Today', 'By Thursday', 'Next week', 'At the final exam'], a: 1, x: '« by Thursday ».' }] },
  { id: 'n05', diff: 2, g: 'W', ctx: 'Listen to an announcement at a campus sports center.', text: 'Good afternoon, everyone, and thank you for your attention. We\'d like to let you know that the swimming pool will be closed all weekend while our maintenance team repairs a problem with the filtration system. We expect it to reopen on Monday at seven a.m., in time for the early swimmers. The gym, the tennis courts, and the climbing wall will all operate as usual, and the fitness classes that normally take place beside the pool have been moved to Studio B. We apologize for any inconvenience this may cause.',
    qs: [{ q: 'Why will the pool be closed?', o: ['A part of its filtration system needs repair', 'There is a swimming competition', 'It is a public holiday', 'It is undergoing routine cleaning'], a: 0, x: '« repairs a problem with the filtration system ».' }, { q: 'When is the pool expected to reopen?', o: ['Monday at seven in the morning', 'Sunday evening', 'Monday at seven in the evening', 'Saturday morning'], a: 0, x: '« on Monday at seven a.m. ».' }, { q: 'What has changed for the fitness classes?', o: ['They have been cancelled', 'They will take place outdoors', 'They have been moved to another room', 'They will start later'], a: 2, x: '« have been moved to Studio B ».' }] },
  { id: 'n06', diff: 2, g: 'M', ctx: 'Listen to an announcement from the career center.', text: 'Hi, everyone. This is a reminder that the spring career fair is next Wednesday in the student union. More than sixty employers will attend, including several major banks and consulting firms. To make the most of it, we strongly recommend attending one of our CV review workshops this week. Spaces are limited, so sign up on the career portal as soon as possible. And don\'t forget to dress professionally on the day.',
    qs: [{ q: 'What is the main purpose of the announcement?', o: ['To announce job offers', 'To cancel the fair', 'To recruit volunteers', 'To promote the career fair and related preparation'], a: 3, x: 'Rappel du forum + ateliers CV.' }, { q: 'What does the speaker recommend doing this week?', o: ['Applying to banks', 'Attending a CV workshop', 'Buying a suit', 'Visiting employers'], a: 1, x: '« attending one of our CV review workshops ».' }, { q: 'Why should students register quickly?', o: ['Workshop places are limited', 'The fair is tomorrow', 'Registration costs more later', 'Employers need the list'], a: 0, x: '« Spaces are limited ».' }] },
  { id: 'n07', diff: 3, g: 'W', ctx: 'Listen to an announcement by a department administrator.', text: 'Good afternoon. As some of you know, the department is moving to a new building over the summer. During the transition, faculty offices will be relocated in stages, so office hours may temporarily take place in the seminar rooms on the ground floor. Please check each instructor\'s page for their current location before showing up. We also ask thesis students to collect any personal belongings from the graduate lounge by June first, after which remaining items will be donated.',
    qs: [{ q: 'Why might office hours be held in seminar rooms?', o: ['Too many students attend', 'The old building is closed', 'Offices are being moved gradually', 'Instructors prefer larger rooms'], a: 2, x: 'Déménagement « in stages ».' }, { q: 'What should students do before going to office hours?', o: ['Email the administrator', 'Check the instructor\'s page for the location', 'Book a seminar room', 'Go to the graduate lounge'], a: 1, x: '« check each instructor\'s page ».' }, { q: 'What will happen to items left in the graduate lounge after June first?', o: ['They will be given away', 'They will be moved to the new building', 'They will be stored', 'They will be returned to students'], a: 0, x: '« will be donated ».' }] },
  { id: 'n08', diff: 2, g: 'M', ctx: 'Listen to an announcement in a campus cafeteria.', text: 'Good afternoon, everyone. Today is International Food Day in the main cafeteria, and we\'re serving a special menu featuring dishes from Mexico, India, and Japan, all prepared by students from those countries. If you sample all three dishes, you\'ll be entitled to a free dessert. To claim it, just show your receipt at the dessert counter before three o\'clock. Please note that a vegetarian option is available for each country, so ask at the counter if you\'re not sure what to choose.',
    qs: [{ q: 'What is special about the cafeteria today?', o: ['All the food is free', 'A new chef is starting', 'It is closing early', 'It is serving a menu inspired by three countries'], a: 3, x: 'Menu spécial : Mexique, Inde, Japon.' }, { q: 'What must students do to claim the free dessert?', o: ['Try all three dishes and show their receipt', 'Show their student ID after trying one dish', 'Fill out a satisfaction survey', 'Order before noon'], a: 0, x: '« sample all three dishes... show your receipt ».' }, { q: 'What can students who do not eat meat do?', o: ['Skip the offer altogether', 'Bring their own food', 'Choose a vegetarian version of each country\'s dish', 'Eat only the dessert'], a: 2, x: '« a vegetarian option is available for each country ».' }] },
  { id: 'n09', diff: 2, g: 'W', ctx: 'Listen to an announcement at the start of a lab session.', text: 'Okay, before we get started with today\'s experiment, two quick safety points. First, the fume hood at station three isn\'t working properly, so no one should use that station today. Second, remember that goggles stay on for the entire session, even when you\'re just writing up your results. Anyone without goggles will be asked to leave. Now, please take out your lab manuals.',
    qs: [{ q: 'Why should students avoid station three?', o: ['Its equipment is not functioning correctly', 'It is reserved', 'It is too crowded', 'It is being cleaned'], a: 0, x: 'La hotte ne fonctionne pas bien.' }, { q: 'When must students wear goggles?', o: ['Only during the experiment', 'Only at station three', 'Only when writing', 'During the whole session'], a: 3, x: '« for the entire session ».' }, { q: 'What will the instructor probably do next?', o: ['End the class', 'Repair the fume hood', 'Begin explaining the experiment', 'Check homework'], a: 2, x: '« please take out your lab manuals ».' }] },
  { id: 'n10', diff: 3, g: 'M', ctx: 'Listen to an announcement from the dean of students.', text: 'Good evening. I\'m writing — or rather, speaking — to let you know about an important change to the course evaluation process. Starting this term, evaluations will be completed during class time in the final week, rather than online afterward. Participation rates had fallen below thirty percent, which made the results difficult to interpret. Responses remain completely anonymous, and instructors will not see them until after final grades are submitted.',
    qs: [{ q: 'What change is being announced?', o: ['Evaluations will be cancelled', 'Course evaluations will be done in class', 'Grades will be posted online', 'Instructors will evaluate students differently'], a: 1, x: 'Évaluations en classe pendant la dernière semaine.' }, { q: 'Why was the change made?', o: ['Students complained about anonymity', 'Too few students completed evaluations online', 'Instructors requested it', 'The online system was hacked'], a: 1, x: 'Participation < 30 %.' }, { q: 'Why does the speaker mention that instructors see responses only after grades are submitted?', o: ['To reassure students that honest feedback will not affect their grades', 'To explain a delay', 'To criticize instructors', 'To encourage negative comments'], a: 0, x: 'Rassurer : pas d\'impact sur les notes.' }] },
  { id: 'n11', diff: 2, g: 'W', ctx: 'Listen to an announcement at the start of an orientation session.', text: 'Welcome to orientation, everyone! Today\'s schedule has changed slightly. The campus tour, which was planned for this morning, will now take place after lunch because of the rain. So we\'ll begin with the presentation on academic resources here in the auditorium. Lunch will be served at twelve thirty in the main dining hall, and your meal tickets are in the welcome packs.',
    qs: [{ q: 'Why was the campus tour rescheduled?', o: ['Because the guide is late', 'Because lunch was moved', 'Because of a meeting', 'Because of the weather'], a: 3, x: '« because of the rain ».' }, { q: 'What will happen first?', o: ['Lunch', 'The campus tour', 'A presentation about academic resources', 'Registration'], a: 2, x: '« we\'ll begin with the presentation ».' }, { q: 'Where can students find their meal tickets?', o: ['At the dining hall', 'In their welcome packs', 'At the auditorium entrance', 'Online'], a: 1, x: '« in the welcome packs ».' }] },
  { id: 'n12', diff: 3, g: 'M', ctx: 'Listen to a professor\'s announcement about an assignment.', text: 'A few of you have asked whether you can use AI tools for the case study. Here\'s my position: you may use them to brainstorm or to check your grammar, but the analysis itself must be your own. If you use such a tool, include a short note at the end explaining how you used it. Undisclosed use will be treated as a breach of academic integrity, not because the tools are forbidden, but because transparency is.',
    qs: [{ q: 'What is the professor\'s policy on AI tools?', o: ['They are completely forbidden', 'They can be used to write the analysis', 'They are required', 'They are allowed for limited purposes if their use is disclosed'], a: 3, x: 'Autorisés pour brainstormer/grammaire, avec mention.' }, { q: 'What must students do if they use an AI tool?', o: ['Ask permission first', 'Submit two versions', 'Add a note explaining how they used it', 'Use it only for grammar'], a: 2, x: '« include a short note at the end ».' }, { q: 'What does the professor mean by the last sentence?', o: ['The real issue is hiding the use of the tools', 'Using AI tools is always cheating', 'Transparency is forbidden', 'Grammar checkers are forbidden'], a: 0, x: 'Le problème, c\'est la dissimulation.' }] },
  { id: 'n13', diff: 2, g: 'W', ctx: 'Listen to an announcement on a campus bus.', text: 'Attention, passengers. Due to road work on Main Street, this bus will not be stopping at the library this afternoon. We recommend that anyone heading to the library get off at the next stop, which is the Student Center, and walk the rest of the way. It should take around five minutes, and the path is clearly signposted. Passengers who need step-free access can stay on board until the Science Building, where the driver will help them transfer to the shuttle. Thank you for your patience.',
    qs: [{ q: 'Why will the bus skip the library stop?', o: ['The library is closed', 'The bus is running late', 'There is road work on Main Street', 'The driver changed the route'], a: 2, x: '« Due to road work on Main Street ».' }, { q: 'What should most passengers going to the library do?', o: ['Stay on the bus until the last stop', 'Wait for the next bus', 'Take a taxi', 'Get off at the Student Center and walk'], a: 3, x: '« get off at the next stop, which is the Student Center, and walk ».' }, { q: 'What is offered to passengers who need step-free access?', o: ['A transfer to the shuttle at the Science Building', 'A taxi paid by the university', 'A different route entirely', 'A ride directly to the library'], a: 0, x: '« stay on board until the Science Building... transfer to the shuttle ».' }] },
  { id: 'n14', diff: 2, g: 'M', ctx: 'Listen to an announcement at the start of a seminar.', text: 'Before we dive in, a quick change to the reading list. The article by Martinez has been replaced with a more recent study, because the original data were revised last month and some of the conclusions no longer hold. The new article is already on the course website. Please read it before Thursday, since we\'ll be discussing it in detail. The rest of the list stays the same.',
    qs: [{ q: 'Why was one article replaced?', o: ['It was too long', 'Its data were revised and some conclusions became invalid', 'Students did not like it', 'The author asked for it'], a: 1, x: '« the original data were revised... conclusions no longer hold ».' }, { q: 'Where can students find the new article?', o: ['In the library', 'In their email', 'On the course website', 'At the bookstore'], a: 2, x: '« already on the course website ».' }, { q: 'When should students read the new article?', o: ['Before Thursday', 'Next week', 'Today', 'Before the final exam'], a: 0, x: '« before Thursday ».' }] },
];

CONTENT.talk = [
  { id: 't01', diff: 2, g: 'W', ctx: 'Listen to part of a lecture in a biology class.', text: 'Today, let\'s talk about camouflage. Many animals avoid predators by blending into their surroundings, but camouflage isn\'t just about color. Take the cuttlefish, for example. It can change not only its color but also the texture of its skin in less than a second, matching rocks, sand, or seaweed. What\'s remarkable is that cuttlefish are thought to be color-blind. So how do they match colors they can\'t see? One hypothesis is that light-sensitive proteins in their skin detect light directly. Another is that they rely on brightness and contrast rather than color itself. Researchers are still debating this, and it\'s a nice reminder that even well-studied behaviors can hold surprises.',
    qs: [{ q: 'What is the talk mainly about?', o: ['How cuttlefish hunt', 'The cuttlefish\'s camouflage abilities and an unresolved question about them', 'Why most animals are color-blind', 'The texture of seaweed'], a: 1, x: 'Camouflage + énigme de la cécité aux couleurs.' }, { q: 'According to the professor, what makes the cuttlefish\'s ability surprising?', o: ['It changes color very slowly', 'It lives only in sand', 'It has no predators', 'It seems unable to see color'], a: 3, x: '« cuttlefish are thought to be color-blind ».' }, { q: 'What is one hypothesis mentioned?', o: ['Their skin may detect light directly', 'Cuttlefish copy other animals', 'They memorize their environment', 'They use sound'], a: 0, x: '« light-sensitive proteins in their skin ».' }, { q: 'Why does the professor say it is "a nice reminder"?', o: ['To show that science is complete', 'To criticize researchers', 'To emphasize that familiar topics can still be mysterious', 'To end the course'], a: 2, x: 'Même des comportements bien étudiés réservent des surprises.' }] },
  { id: 't02', diff: 3, g: 'M', ctx: 'Listen to part of a lecture in an economics class.', text: 'Let\'s turn to the concept of moral hazard. Moral hazard arises when one party is protected from the consequences of its own risky behavior, so it has less incentive to be careful. Insurance is the classic case: someone with full car insurance might drive a bit less cautiously. But the concept became front-page news after the 2008 financial crisis. When governments rescued large banks, critics argued this created moral hazard on a massive scale. If banks believe they\'re "too big to fail," they may take on excessive risk, knowing that taxpayers will absorb the losses. Now, regulators responded by requiring banks to hold more capital, essentially forcing shareholders to have more skin in the game. Whether that\'s been enough is still hotly debated.',
    qs: [{ q: 'What is the main topic of the talk?', o: ['Moral hazard and its role in banking', 'The history of car insurance', 'How to prevent car accidents', 'Taxpayer rights'], a: 0, x: 'Définition du risque moral puis application aux banques.' }, { q: 'Why does the professor mention car insurance?', o: ['To compare insurers and banks\' profits', 'To recommend full coverage', 'To criticize drivers', 'To give a simple example of moral hazard'], a: 3, x: 'Exemple classique.' }, { q: 'What does "too big to fail" imply in this context?', o: ['Banks are too large to manage', 'Banks expect to be rescued if they get into trouble', 'Banks cannot make losses', 'Banks are protected by shareholders'], a: 1, x: 'Elles s\'attendent à être sauvées.' }, { q: 'What is the purpose of higher capital requirements, according to the professor?', o: ['To increase bank profits', 'To lower interest rates', 'To reduce taxes', 'To make shareholders bear more of the risk'], a: 3, x: '« skin in the game » = les actionnaires assument davantage le risque.' }] },
  { id: 't03', diff: 2, g: 'W', ctx: 'Listen to part of a talk in an environmental science class.', text: 'Good morning. Today we\'re looking at urban heat islands, the phenomenon whereby a city is noticeably warmer than the rural land around it, by several degrees Celsius, especially at night. There are a few contributing factors. First, materials such as concrete and asphalt absorb heat during the day and slowly release it after sunset, so cities never cool down properly overnight. Second, cities have far less vegetation, and plants normally cool the air by releasing water vapor. Third, traffic, factories, and air conditioning units all give off waste heat. The encouraging part is that cities aren\'t powerless. Planting trees, installing green roofs, and painting roofs and roads in lighter colors, which reflect more sunlight, can all bring temperatures down.',
    qs: [{ q: 'What is an urban heat island?', o: ['A city that is warmer than the countryside around it', 'A park located inside a city', 'An island close to a coastal city', 'A building with powerful air conditioning'], a: 0, x: 'Une ville nettement plus chaude que la campagne environnante.' }, { q: 'Why do cities not cool down properly at night?', o: ['There is less wind at night', 'Concrete and asphalt release the heat they absorbed', 'Street lighting heats the air', 'Plants release heat after dark'], a: 1, x: '« absorb heat during the day and slowly release it after sunset ».' }, { q: 'Which of the following is NOT mentioned as a cause of urban heat islands?', o: ['Waste heat from traffic and air conditioners', 'Heat-absorbing building materials', 'Ocean currents', 'A shortage of vegetation'], a: 2, x: 'Les courants océaniques ne sont pas mentionnés.' }, { q: 'Why do lighter-colored roofs and roads help?', o: ['They absorb more noise', 'They help plants grow', 'They reduce traffic', 'They reflect more sunlight'], a: 3, x: '« lighter colors, which reflect more sunlight ».' }] },
  { id: 't04', diff: 2, g: 'M', ctx: 'Listen to part of a lecture in a psychology class.', text: 'So, the bystander effect. In the 1960s, psychologists John Darley and Bibb Latané ran experiments showing that people are less likely to help someone in need when other people are present. In one study, participants heard what sounded like another student having a seizure. When they believed they were alone, most of them went for help quickly. But when they believed four other people could also hear, many never went for help at all. Darley and Latané explained this through diffusion of responsibility: when many people are present, each person feels less personally responsible. Interestingly, more recent research using real-life camera footage suggests that in actual public conflicts, someone intervenes in the vast majority of cases. So the effect may be weaker in real life than the lab suggested.',
    qs: [{ q: 'What did the early experiments show?', o: ['People help more when others are present', 'People help less when others are present', 'Groups always ignore emergencies', 'Students rarely have seizures'], a: 1, x: 'Moins d\'aide en présence d\'autres personnes.' }, { q: 'What is "diffusion of responsibility"?', o: ['The feeling that responsibility is shared among many people', 'A medical condition', 'A legal rule', 'A type of training'], a: 0, x: 'Chacun se sent moins responsable.' }, { q: 'Why does the professor mention camera footage?', o: ['To confirm the lab results exactly', 'To show how experiments are recorded', 'To present evidence that the effect may be weaker in real life', 'To criticize the use of cameras'], a: 2, x: 'Dans la vraie vie, quelqu\'un intervient dans la grande majorité des cas.' }, { q: 'What can be inferred about the professor\'s view?', o: ['The bystander effect is completely false', 'Darley and Latané were dishonest', 'Laboratory findings should be checked against real-world data', 'People never help strangers'], a: 2, x: 'Nuance entre laboratoire et réalité.' }] },
  { id: 't05', diff: 3, g: 'W', ctx: 'Listen to part of a lecture in an art history class.', text: 'I want to spend a few minutes on the Dutch Golden Age, roughly the seventeenth century. What\'s unusual about this period is the art market itself. In most of Europe, painters depended on patrons, the church, the aristocracy, who commissioned specific works. In the Dutch Republic, by contrast, a prosperous merchant class bought paintings on the open market, often ready-made, from dealers or even at fairs. This had a profound effect on subject matter. Instead of grand religious scenes, you see still lifes, landscapes, and everyday domestic interiors, subjects that appealed to middle-class buyers decorating their homes. Painters also began to specialize. One artist might paint only seascapes, another only flowers, which allowed them to work efficiently and build a recognizable brand, so to speak. In a sense, it was one of the first genuinely commercial art markets.',
    qs: [{ q: 'What is the main point of the lecture?', o: ['Dutch painters were mostly religious', 'The structure of the Dutch art market shaped the art that was produced', 'Seascapes were the most expensive paintings', 'The aristocracy controlled Dutch art'], a: 1, x: 'Le marché a influencé les sujets.' }, { q: 'How did the Dutch art market differ from the rest of Europe?', o: ['Paintings were sold on an open market to merchants', 'The church bought most paintings', 'Painting was forbidden', 'Artists were paid by the state'], a: 0, x: 'Marché ouvert, marchands, foires.' }, { q: 'Why did painters specialize?', o: ['It was required by law', 'Their patrons demanded it', 'Materials were limited', 'It helped them work efficiently and be recognized'], a: 3, x: 'Efficacité + « recognizable brand ».' }, { q: 'Why does the professor say "so to speak"?', o: ['To correct a mistake', 'To quote a painter', 'To introduce a question', 'To show that she is using a modern business term loosely'], a: 3, x: 'Elle applique un terme moderne (« brand ») de façon approximative.' }] },
  { id: 't06', diff: 2, g: 'M', ctx: 'Listen to part of a talk in a geology class.', text: 'Let\'s consider how scientists date rocks. One of the most important methods is radiometric dating. Certain elements are unstable, which means they gradually transform into other elements at a constant rate. For example, uranium slowly decays into lead. The time it takes for half of the uranium in a sample to change is called its half-life, and for one form of uranium, that\'s about four and a half billion years. So, by measuring the ratio of uranium to lead in a mineral, geologists can calculate how long ago it formed. Using this technique, scientists have estimated that the Earth itself is about four point five billion years old.',
    qs: [{ q: 'What is the talk mainly about?', o: ['How uranium is mined', 'The formation of lead', 'A method for determining the age of rocks', 'Dangerous elements'], a: 2, x: 'La datation radiométrique.' }, { q: 'What is a half-life?', o: ['The time for half of an unstable element in a sample to transform', 'Half the age of the Earth', 'The time a rock takes to form', 'The life of a geologist'], a: 0, x: 'Définition donnée.' }, { q: 'What do geologists measure to date a mineral?', o: ['Its weight', 'The ratio between uranium and lead', 'Its color', 'Its temperature'], a: 1, x: '« the ratio of uranium to lead ».' }, { q: 'What conclusion has this method allowed?', o: ['Uranium is disappearing', 'All rocks are the same age', 'Lead is unstable', 'The Earth is about 4.5 billion years old'], a: 3, x: 'Âge de la Terre.' }] },
  { id: 't07', diff: 3, g: 'W', ctx: 'Listen to part of a lecture in a business class.', text: 'Today\'s topic is disruptive innovation, a term coined by Clayton Christensen. Now, people often use "disruptive" to mean any exciting new technology, but that\'s not what Christensen meant. In his theory, disruption typically starts at the bottom of a market. A newcomer offers a product that\'s cheaper and simpler, and frankly worse by traditional standards, so established firms ignore it. Their best customers don\'t want it, and the margins are low. But the newcomer improves steadily, and eventually it becomes good enough for mainstream customers, at which point the incumbents are in trouble. The paradox is that the established companies weren\'t badly managed. They did exactly what good management recommends, listening to their most profitable customers. That rational behavior is precisely what left them vulnerable.',
    qs: [{ q: 'What misconception does the professor address?', o: ['That innovation is always expensive', 'That newcomers never succeed', 'That "disruptive" simply means any exciting new technology', 'That Christensen studied only technology firms'], a: 2, x: 'Ce n\'est pas n\'importe quelle nouveauté.' }, { q: 'According to the theory, where does disruption usually begin?', o: ['At the low end of the market, with simpler products', 'At the high end of the market', 'In government research', 'Among the best customers'], a: 0, x: '« starts at the bottom of a market ».' }, { q: 'Why do established firms initially ignore the newcomer?', o: ['It is illegal', 'Its product appeals little to their best customers and offers low margins', 'It is too expensive', 'They have not heard of it'], a: 1, x: 'Clients rentables pas intéressés, marges faibles.' }, { q: 'What is the paradox the professor describes?', o: ['Good management practices can make firms vulnerable', 'Poorly managed firms survive', 'Cheap products are always better', 'Customers do not know what they want'], a: 0, x: 'Le comportement rationnel les a rendues vulnérables.' }] },
  { id: 't08', diff: 2, g: 'M', ctx: 'Listen to part of a talk in a history class.', text: 'Today we\'ll be talking about the Great Wall of China, and I want to start by clearing up a couple of misconceptions. First, people tend to imagine a single continuous wall, but it\'s actually a network of walls and fortifications built by different dynasties over more than two thousand years. The sections that tourists usually visit, the ones you see in photographs, were mostly built during the Ming dynasty, roughly five hundred years ago. Their main purpose was defensive, protecting the empire against raids from the north, but they also helped the authorities regulate trade and monitor the movement of people along the frontier. The second myth is that the wall is visible from space with the naked eye. Astronauts say that\'s not the case. It is extremely long, but it\'s far too narrow to pick out from orbit.',
    qs: [{ q: 'What is the first misconception the speaker corrects?', o: ['That the wall is located in China', 'That the wall is one continuous structure', 'That the wall is very old', 'That tourists can visit it'], a: 1, x: '« a network of walls... built by different dynasties ».' }, { q: 'When were the sections most tourists visit mostly built?', o: ['During the Ming dynasty', 'More than two thousand years ago', 'In the twentieth century', 'During the first dynasty'], a: 0, x: '« mostly built during the Ming dynasty, roughly five hundred years ago ».' }, { q: 'Besides defense, what was one function of the walls?', o: ['Marking the border with Japan', 'Storing food for armies', 'Regulating trade and the movement of people', 'Attracting tourists'], a: 2, x: '« regulate trade and monitor the movement of people ».' }, { q: 'Why can\'t the wall be seen from space with the naked eye?', o: ['It is too short', 'It is usually hidden by clouds', 'Most of it has been destroyed', 'It is too narrow'], a: 3, x: '« far too narrow to pick out from orbit ».' }] },
  { id: 't09', diff: 2, g: 'W', ctx: 'Listen to part of a lecture in a linguistics class.', text: 'Let\'s look at how children acquire language. One striking observation is what we call overregularization. At some point, a child who correctly said "went" suddenly starts saying "goed." Parents sometimes worry that their child is getting worse. But linguists see it as a sign of progress. Why? Because the child has discovered a rule, add "-ed" for the past tense, and is now applying it everywhere, even where it doesn\'t belong. Earlier, "went" was simply memorized as a separate word. Eventually, the child learns the exceptions, and "went" comes back. This U-shaped pattern, correct, then incorrect, then correct again, shows that children aren\'t just imitating adults; after all, adults never say "goed."',
    qs: [{ q: 'What is overregularization?', o: ['Speaking too slowly', 'Learning two languages', 'Repeating adults exactly', 'Using a grammatical rule in cases where it does not apply'], a: 3, x: 'Appliquer une règle partout, même aux exceptions.' }, { q: 'Why do linguists view "goed" as progress?', o: ['It is correct in some dialects', 'It shows the child has learned a general rule', 'It is easier to pronounce', 'It shows better memory'], a: 1, x: 'L\'enfant a découvert la règle du -ed.' }, { q: 'What does the "U-shaped pattern" refer to?', o: ['The shape of the mouth', 'Increasing vocabulary', 'Correct use, then errors, then correct use again', 'A drawing test'], a: 2, x: 'Correct → incorrect → correct.' }, { q: 'Why does the professor say adults never say "goed"?', o: ['To show children are not simply imitating', 'To criticize parents', 'To explain regional accents', 'To show adults make fewer mistakes'], a: 0, x: 'Preuve qu\'ils ne font pas qu\'imiter.' }] },
  { id: 't10', diff: 3, g: 'M', ctx: 'Listen to part of a lecture in a finance class.', text: 'Let\'s discuss why stock prices sometimes seem to overreact. Consider a company that reports three consecutive quarters of strong earnings. Investors tend to extrapolate, assuming the trend will continue indefinitely, and they bid the price up well beyond what the fundamentals justify. Then, when growth inevitably slows, the correction can be brutal. Researchers Werner De Bondt and Richard Thaler found evidence consistent with this. Portfolios of stocks that had performed worst over the previous three to five years subsequently outperformed the prior winners. Now, this finding is controversial. Defenders of market efficiency argue that the "losers" were simply riskier, so their higher returns were compensation for that risk, not evidence of irrationality. Separating these two explanations empirically turns out to be remarkably difficult.',
    qs: [{ q: 'According to the professor, why might investors overreact to strong earnings?', o: ['They assume past trends will continue', 'They lack access to information', 'They are forced to buy by regulators', 'They expect prices to fall'], a: 0, x: 'Extrapolation de la tendance.' }, { q: 'What did De Bondt and Thaler find?', o: ['Past winners continued to outperform', 'Prices always reflect fundamentals', 'Past losers later outperformed past winners', 'Earnings do not affect prices'], a: 2, x: 'Les perdants ont ensuite surperformé.' }, { q: 'How do defenders of market efficiency interpret the finding?', o: ['As proof of irrationality', 'As a statistical error', 'As insider trading', 'As compensation for higher risk'], a: 3, x: 'Rendement plus élevé = prime de risque.' }, { q: 'What does the professor suggest in the last sentence?', o: ['The debate is easily resolved', 'It is hard to determine which explanation is correct', 'Efficiency has been disproved', 'Research should stop'], a: 1, x: '« remarkably difficult ».' }] },
  { id: 't11', diff: 2, g: 'W', ctx: 'Listen to part of a lecture in an astronomy class.', text: 'Why do we have seasons? A common answer is that the Earth is closer to the Sun in summer. That sounds logical, but it\'s wrong. In fact, the Earth is closest to the Sun in early January, which is winter in the Northern Hemisphere. The real reason is the tilt of the Earth\'s axis, about twenty-three and a half degrees. When the Northern Hemisphere is tilted toward the Sun, sunlight hits it more directly and days are longer, so it\'s summer there. At the same time, the Southern Hemisphere is tilted away, so it experiences winter. That\'s also why seasons are reversed between, say, France and Australia.',
    qs: [{ q: 'What misconception does the professor mention?', o: ['That the Earth has no tilt', 'That seasons are caused by distance from the Sun', 'That Australia has no seasons', 'That January is summer everywhere'], a: 1, x: 'La distance n\'est pas la cause.' }, { q: 'When is the Earth closest to the Sun?', o: ['In July', 'In early January', 'In spring', 'It never changes'], a: 1, x: '« early January ».' }, { q: 'What actually causes the seasons?', o: ['The Earth\'s tilted axis', 'Changes in the Sun\'s temperature', 'The Moon', 'Ocean currents'], a: 0, x: 'L\'inclinaison de l\'axe.' }, { q: 'Why does the professor mention France and Australia?', o: ['To compare their climates', 'To illustrate that seasons are opposite in the two hemispheres', 'To show where astronomy began', 'To discuss time zones'], a: 1, x: 'Saisons inversées.' }] },
  { id: 't12', diff: 3, g: 'M', ctx: 'Listen to part of a lecture in a sociology class.', text: 'Robert Putnam\'s book "Bowling Alone" argued that American social capital declined sharply in the late twentieth century. By social capital, Putnam meant the networks, norms, and trust that enable people to cooperate. His famous illustration was that more Americans were bowling than ever, but fewer were bowling in organized leagues. Why does that matter? Because leagues bring together people who might not otherwise interact, building trust that spills over into civic life. Putnam pointed to several causes, but he singled out television as a major one, since it privatized leisure time. Critics, however, argued that he overlooked new forms of association, such as advocacy groups and, later, online communities. Whether these newer forms generate the same kind of trust remains an open question.',
    qs: [{ q: 'What is social capital, according to Putnam?', o: ['Money invested in communities', 'The number of bowling alleys', 'Networks, norms, and trust that facilitate cooperation', 'Government funding for clubs'], a: 2, x: 'Définition donnée.' }, { q: 'Why does the professor mention bowling leagues?', o: ['To show that bowling became less popular', 'To promote bowling', 'To explain television ratings', 'To illustrate a decline in organized group activities'], a: 3, x: 'Plus de joueurs, moins de ligues.' }, { q: 'What cause did Putnam emphasize?', o: ['Economic crisis', 'Television', 'Immigration', 'Urban planning'], a: 1, x: 'La télévision a privatisé les loisirs.' }, { q: 'What did critics argue?', o: ['Bowling leagues were growing', 'Trust had increased', 'Putnam ignored newer kinds of groups', 'Television was harmless'], a: 2, x: '« overlooked new forms of association ».' }] },
  { id: 't13', diff: 2, g: 'W', ctx: 'Listen to part of a talk in a nutrition class.', text: 'Today I want to look at a claim you\'ve all heard: that breakfast is the most important meal of the day. Is it actually true? Well, the research is more mixed than you might expect. Several large studies found that people who regularly eat breakfast tend to be healthier and slimmer. But those people also tend to exercise more, smoke less, and generally lead healthier lives, so it\'s very difficult to say whether breakfast itself is responsible. When researchers ran controlled experiments, assigning some people to eat breakfast and others to skip it, the results were far less impressive. Skipping breakfast didn\'t consistently lead to weight gain. What seems to matter much more is the overall quality of your diet across the whole day rather than the timing of one particular meal.',
    qs: [{ q: 'What question does the talk examine?', o: ['Whether breakfast really is the most important meal', 'How to prepare a healthy breakfast', 'Why people skip lunch', 'How much people should exercise'], a: 0, x: 'Le petit-déjeuner est-il vraiment le repas le plus important ?' }, { q: 'Why are the early studies difficult to interpret?', o: ['The studies involved too few people', 'Participants lied about what they ate', 'Scientists could not agree on a definition of breakfast', 'Breakfast eaters also tend to have other healthy habits'], a: 3, x: 'Ceux qui prennent un petit-déjeuner font aussi plus de sport et fument moins : biais de confusion.' }, { q: 'What did the controlled experiments show?', o: ['Skipping breakfast always causes weight gain', 'Breakfast should be the largest meal', 'People should eat five meals a day', 'Skipping breakfast did not reliably cause weight gain'], a: 3, x: '« didn\'t consistently lead to weight gain ».' }, { q: 'What is the speaker\'s conclusion?', o: ['Everyone must eat breakfast', 'Overall diet quality matters more than meal timing', 'Breakfast is harmful', 'Nutrition research is useless'], a: 1, x: '« the overall quality of your diet across the whole day ».' }] },
  { id: 't14', diff: 2, g: 'M', ctx: 'Listen to part of a lecture in a marketing class.', text: 'Let\'s talk about the decoy effect. Imagine a cinema selling popcorn in two sizes: small for three dollars and large for seven. Most people buy the small one. Now the cinema adds a medium size for six fifty. Suddenly, many more people buy the large. Why? Because next to the medium, the large looks like a bargain; for just fifty cents more, you get much more popcorn. The medium size isn\'t really meant to be bought. It\'s a decoy, designed to make the large option look better by comparison. This shows that our choices depend not only on the options themselves, but on how they compare to each other.',
    qs: [{ q: 'What happens when the medium size is introduced?', o: ['More people buy the large', 'Most people buy the medium', 'Sales of popcorn fall', 'The small becomes more popular'], a: 0, x: 'Plus de grands formats vendus.' }, { q: 'What is the purpose of the decoy?', o: ['To be the best-selling product', 'To reduce prices', 'To make another option look more attractive', 'To confuse employees'], a: 2, x: 'Faire paraître le grand format avantageux.' }, { q: 'Why does the large size look like a bargain?', o: ['It costs only slightly more than the medium', 'It is cheaper than the small', 'It is on sale', 'It includes a drink'], a: 0, x: '50 centimes de plus seulement.' }, { q: 'What general point does the professor make?', o: ['People always choose the cheapest option', 'Popcorn is overpriced', 'Consumers are always rational', 'Choices are influenced by comparisons between options'], a: 3, x: 'Les choix dépendent des comparaisons.' }] },
  { id: 't15', diff: 3, g: 'W', ctx: 'Listen to part of a lecture in an ecology class.', text: 'We often assume that removing an invasive species will automatically help native wildlife. But ecosystems are more tangled than that. Consider islands where cats were introduced and began preying on seabirds. On one sub-Antarctic island, conservationists eradicated the cats, expecting the birds to recover. Instead, the rabbit population, which the cats had kept in check, exploded. The rabbits stripped much of the island\'s vegetation, damaging the very habitat the seabirds depended on. Eventually, a costly second campaign was needed to remove the rabbits. The lesson isn\'t that eradication is a bad idea; it\'s that managers need to model the whole food web before intervening, because a predator may be suppressing another invasive species.',
    qs: [{ q: 'What assumption does the professor challenge?', o: ['That cats are harmless', 'That removing an invasive species always benefits native wildlife', 'That rabbits eat birds', 'That islands have simple ecosystems'], a: 1, x: 'Retirer une espèce invasive n\'aide pas forcément.' }, { q: 'What happened after the cats were removed?', o: ['The seabirds recovered immediately', 'The vegetation grew back', 'The rabbit population increased dramatically', 'The cats returned'], a: 2, x: '« the rabbit population... exploded ».' }, { q: 'How did the rabbits harm the seabirds?', o: ['By eating their eggs', 'By spreading disease', 'By competing for fish', 'By destroying vegetation the birds relied on'], a: 3, x: 'Destruction de l\'habitat.' }, { q: 'What is the professor\'s main lesson?', o: ['Eradication should never be attempted', 'Cats should be introduced to islands', 'The entire food web should be analyzed before intervening', 'Rabbits are the most dangerous species'], a: 2, x: '« model the whole food web before intervening ».' }] },
  { id: 't16', diff: 2, g: 'M', ctx: 'Listen to part of a lecture in a history of technology class.', text: 'When we think of the invention of the light bulb, we usually think of Thomas Edison. But Edison didn\'t invent the first electric light. Several inventors, including Joseph Swan in England, had produced working bulbs before him. Their problem was that the bulbs burned out very quickly. Edison\'s real achievement was making the light bulb practical and long-lasting, by testing thousands of materials for the filament. Even more important, he built an entire system around it: power stations, wiring, and meters to charge customers. In other words, Edison\'s genius was less about a single invention and more about creating the infrastructure that made electric lighting a business.',
    qs: [{ q: 'What misconception does the professor correct?', o: ['That Swan was American', 'That Edison invented the first electric light', 'That light bulbs use filaments', 'That Edison built power stations'], a: 1, x: 'D\'autres avaient fait des ampoules avant.' }, { q: 'What was the problem with earlier bulbs?', o: ['They did not last long', 'They were too bright', 'They were too expensive to buy', 'They used too much gas'], a: 0, x: '« burned out very quickly ».' }, { q: 'According to the professor, what was Edison\'s most important contribution?', o: ['Inventing the filament', 'Working with Swan', 'Building a complete system for electric lighting', 'Selling bulbs in England'], a: 2, x: 'L\'infrastructure complète.' }, { q: 'Why does the professor mention meters?', o: ['To criticize high prices', 'To explain how bulbs work', 'To describe Swan\'s invention', 'As part of the system that turned lighting into a business'], a: 3, x: 'Pour facturer les clients : modèle économique.' }] },
  { id: 't17', diff: 3, g: 'W', ctx: 'Listen to part of a lecture in a political science class.', text: 'Let\'s examine the paradox of voting, first formalized by Anthony Downs. From a strictly rational perspective, voting seems puzzling. The probability that your single vote will decide an election is astronomically small, while voting has real costs: time, travel, gathering information. So a purely self-interested calculation would suggest staying home. Yet millions of people vote. How do we explain this? One response is that people derive intrinsic satisfaction from voting, a sense of civic duty. Critics object that this rescues the theory by simply adding whatever preference is needed, which makes it unfalsifiable. Another approach suggests people think of voting as part of a group, reasoning that if people like them vote, their side can win. The debate is useful precisely because it exposes the limits of narrow rational-choice models.',
    qs: [{ q: 'What is the "paradox of voting"?', o: ['People vote even though a single vote is extremely unlikely to change the result', 'Elections are always close', 'Rational people never vote', 'Voting is free'], a: 0, x: 'Coûts réels, influence quasi nulle, et pourtant on vote.' }, { q: 'What criticism is made of the "civic duty" explanation?', o: ['It is too expensive', 'It makes the theory impossible to test', 'It ignores group behavior', 'It is supported by no one'], a: 1, x: '« unfalsifiable ».' }, { q: 'What does the group-based approach suggest?', o: ['People think about the combined effect of similar voters', 'People vote to meet friends', 'Groups force people to vote', 'People vote randomly'], a: 0, x: 'Raisonner comme membre d\'un groupe.' }, { q: 'Why does the professor consider the debate useful?', o: ['It proves people are irrational', 'It predicts election results', 'It ends the discussion', 'It reveals weaknesses of narrow rational-choice models'], a: 3, x: '« exposes the limits of narrow rational-choice models ».' }] },
  { id: 't18', diff: 2, g: 'M', ctx: 'Listen to part of a talk in an introduction to business class.', text: 'Let\'s talk about why some small businesses fail. The obvious explanation is a bad product, and sometimes that really is the story. But far more often, the culprit is cash flow. A business can look profitable on paper and still run out of money. How is that possible? Imagine a company that sells a great deal of merchandise but allows its customers to pay sixty days after delivery. In the meantime, it still has to pay rent, salaries, and its own suppliers every single month. If it doesn\'t have enough cash in the bank to cover those bills while it waits, it can go under even though sales are booming. That\'s why experienced managers monitor cash flow just as closely as they monitor profit.',
    qs: [{ q: 'According to the speaker, what is a very common cause of small-business failure?', o: ['Too many customers', 'Cash-flow problems', 'An excellent product', 'Low rent'], a: 1, x: 'La trésorerie, plus souvent que le produit.' }, { q: 'How can a profitable company run out of money?', o: ['It sells too few products', 'It has no suppliers to pay', 'Its customers pay late while its own bills fall due now', 'It pays no salaries'], a: 2, x: 'Clients payant à 60 jours, charges à régler chaque mois.' }, { q: 'Which costs does the speaker mention?', o: ['Advertising and taxes', 'Travel and staff training', 'Rent, salaries, and supplier payments', 'Insurance and loan interest'], a: 2, x: '« rent, salaries, and its own suppliers ».' }, { q: 'What is the speaker\'s main advice to managers?', o: ['Focus only on profit', 'Avoid selling on credit to anyone', 'Sell as many products as possible', 'Monitor cash flow as closely as profit'], a: 3, x: '« monitor cash flow just as closely as they monitor profit ».' }] },
];
